const platform = $json;
const now = new Date();
const dayMs = 24 * 60 * 60 * 1000;
const lastSuccess = platform.last_success_at ? new Date(platform.last_success_at) : null;
const isWeekly = lastSuccess && !Number.isNaN(lastSuccess.getTime());
const periodStart = isWeekly ? lastSuccess : new Date(now.getTime() - 30 * dayMs);
const rawAccount = String(platform.username || platform.platform_url || '').trim();
let tiktokUsername = rawAccount.replace(/^@/, '').split('?')[0].replace(/[/]$/, '');
try {
  const parsedUrl = new URL(rawAccount);
  const handle = parsedUrl.pathname.split('/').filter(Boolean).find(part => part.startsWith('@'));
  if (handle) tiktokUsername = handle.slice(1);
} catch {}
return { json: {
  ...platform,
  client_data: Array.isArray(platform.clients) ? platform.clients[0] : platform.clients,
  sync_type: isWeekly ? 'weekly' : 'initial_historical',
  period_start: periodStart.toISOString(),
  period_end: now.toISOString(),
  metrics_period_start: new Date(now.getTime() - 30 * dayMs).toISOString(),
  tiktok_username: tiktokUsername,
  sync_platform: 'tiktok'
} };

