const platform = $('Determine TikTok Sync Period').first().json;
const periodStart = new Date(platform.metrics_period_start).getTime();
const periodEnd = new Date(platform.period_end).getTime();
const numberOrZero = value => {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.trunc(parsed) : 0;
};
const toIsoDate = video => {
  const raw = video.createTimeISO ?? video.createTime;
  if (typeof raw === 'number') return new Date(raw * 1000).toISOString();
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
};
const rawItems = items.map(item => item.json);
const failures = rawItems.filter(item => item?.error || item?.errorCode || item?.errorDescription || item?.requestErrorMessages);
const videos = [];
for (const video of rawItems) {
  const videoId = video.id ?? video.videoId;
  const videoUrl = video.webVideoUrl ?? video.videoUrl;
  const publishedAt = toIsoDate(video);
  if (!videoId || !videoUrl || !publishedAt) continue;
  const publishedTime = new Date(publishedAt).getTime();
  if (publishedTime < periodStart || publishedTime >= periodEnd) continue;
  videos.push({
    video_id: String(videoId),
    video_url: String(videoUrl),
    description: String(video.text ?? video.description ?? '').trim() || null,
    published_at: publishedAt,
    play_count: numberOrZero(video.playCount),
    digg_count: numberOrZero(video.diggCount),
    comment_count: numberOrZero(video.commentCount),
    share_count: numberOrZero(video.shareCount),
    raw_data: {
      author: video.authorMeta?.name ?? null,
      hashtags: Array.isArray(video.hashtags) ? video.hashtags : [],
      collect_count: numberOrZero(video.collectCount),
      is_pinned: Boolean(video.isPinned)
    }
  });
}
return [{ json: {
  ...platform,
  fetch_succeeded: videos.length > 0 || failures.length === 0,
  has_videos: videos.length > 0,
  videos
} }];

const platform =
  $('Continue TikTok Platform').first().json;

const comments = items
  .filter(item =>
    item.json.id &&
    item.json.comment_text
  )
  .map(item => ({
    // رقم السجل داخل جدول tiktok_comments
    source_record_id: item.json.id,

    // معرف التعليق الأصلي في TikTok
    tiktok_comment_id:
      item.json.tiktok_comment_id,

    video_id:
      item.json.video_id || null,

    // اسم العمود في الجدول commenter_username
    author_username:
      item.json.commenter_username || null,

    video_url:
      item.json.video_url || null,

    comment_text:
      item.json.comment_text,

    // اسم العمود في الجدول comment_date
    posted_at:
      item.json.comment_date || null,

    // الجدول يحتوي like_count كعمود منفصل
    public_metrics: {
      like_count: Number(
        item.json.like_count || 0
      )
    }
  }));

if (!comments.length) {
  return [];
}

return [
  {
    json: {
      client_id: platform.client_id,
      branch_id:
        platform.branch_id ?? null,
      platform_id:
        platform.platform_id,

      platform_name: 'tiktok',
      source_table: 'tiktok_comments',

      comments
    }
  }
];

const batch = $('Create TikTok AI Batch').item.json;

let text =
  $json.text ||
  $json.output?.[0]?.content?.[0]?.text ||
  $json.message?.content ||
  $json.content?.find(
    item => item.type === 'output_text'
  )?.text ||
  '';

text = String(text)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

if (!text) {
  throw new Error(
    'لم يتم العثور على نتيجة تحليل تعليقات TikTok'
  );
}

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error(
    'نتيجة الذكاء الاصطناعي ليست JSON صالحًا'
  );
}

if (!Array.isArray(parsed.results)) {
  throw new Error(
    'الحقل results غير موجود أو ليس مصفوفة'
  );
}

const comments = Array.isArray(batch.comments)
  ? batch.comments
  : [];

const commentMap = new Map(
  comments.map(comment => [
    String(comment.source_record_id),
    comment
  ])
);

// التعليقات التي أُرسلت للنموذج
const expectedIds = new Set(
  comments.map(comment =>
    String(comment.source_record_id)
  )
);

// التعليقات التي أعاد النموذج تحليلها
const returnedIds = new Set(
  parsed.results
    .map(result =>
      result.source_record_id ?? result.id
    )
    .filter(id =>
      id !== undefined && id !== null
    )
    .map(id => String(id))
);

// أي تعليق ناقص سيبقى pending ويعاد تحليله
const missingIds = [...expectedIds].filter(
  id => !returnedIds.has(id)
);

if (missingIds.length > 0) {
  console.log(
    `سيعاد تحليل تعليقات TikTok الناقصة: ${missingIds.join(', ')}`
  );
}

const toBoolean = value =>
  value === true || value === 'true';

const allowedSentiments = [
  'positive',
  'negative',
  'neutral'
];

const allowedSeverities = [
  'low',
  'medium',
  'high'
];

const output = [];

for (const result of parsed.results) {
  const sourceRecordId =
    result.source_record_id ??
    result.id;

  if (
    sourceRecordId === undefined ||
    sourceRecordId === null
  ) {
    console.log(
      'تم تجاهل نتيجة لا تحتوي على source_record_id'
    );
    continue;
  }

  const originalComment = commentMap.get(
    String(sourceRecordId)
  );

  // تجاهل أي معرف اخترعه النموذج
  if (!originalComment) {
    console.log(
      `تم تجاهل معرف غير موجود في الدفعة: ${sourceRecordId}`
    );
    continue;
  }

  const sentiment = allowedSentiments.includes(
    result.sentiment
  )
    ? result.sentiment
    : 'neutral';

  const severity = allowedSeverities.includes(
    result.severity
  )
    ? result.severity
    : 'low';

  const category = Array.isArray(result.category)
    ? result.category
    : [result.category || 'أخرى'];

  output.push({
    json: {
      client_id: batch.client_id,
      branch_id: batch.branch_id ?? null,
      platform_id: batch.platform_id,

      platform_name: 'tiktok',
      source_table: 'tiktok_comments',

      // رقم السجل داخل جدول tiktok_comments
      source_record_id: Number(sourceRecordId),

      // معرف تعليق TikTok الأصلي
      external_id:
        originalComment.tiktok_comment_id ||
        null,

      sentiment,
      category,
      severity,

      needs_reply:
        toBoolean(result.needs_reply),

      is_sales_opportunity:
        toBoolean(result.is_sales_opportunity),

      is_complaint:
        toBoolean(result.is_complaint),

      suggested_reply:
        result.suggested_reply || null,

      reason:
        result.reason || null,

      analysis_summary:
        result.analysis_summary || null,

      analysis_status: 'completed',
      model_name: 'gpt-4o-mini',
      analyzed_at: new Date().toISOString()
    }
  });
}

return output;

const platform =
  $('Determine TikTok Sync Period').first().json;

return [
  {
    json: {
      client_id: platform.client_id,
      branch_id: platform.branch_id ?? null,
      platform_id: platform.id,
      platform_name: 'tiktok'
    }
  }
];

const platform = $('Normalize TikTok Videos').first().json;
const rows = items.flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const existingCounts = new Map(rows.filter(row => row?.video_id).map(row => [String(row.video_id), Number(row.comment_count || 0)]));
const now = new Date().toISOString();
const videos = platform.videos ?? [];
const videoRows = videos.map(video => ({
  client_id: platform.client_id,
  branch_id: platform.branch_id ?? null,
  platform_id: platform.id,
  video_id: video.video_id,
  video_url: video.video_url,
  description: video.description,
  published_at: video.published_at,
  play_count: video.play_count,
  digg_count: video.digg_count,
  comment_count: video.comment_count,
  share_count: video.share_count,
  last_scraped_at: now,
  raw_data: video.raw_data,
  updated_at: now
}));
const commentTargets = videos.filter(video => {
  const oldCount = existingCounts.get(String(video.video_id));
  return video.comment_count > 0 && (oldCount === undefined || video.comment_count > oldCount);
});
return [{ json: {
  ...platform,
  video_rows: videoRows,
  comment_target_urls: commentTargets.map(video => video.video_url),
  comment_target_videos: commentTargets
} }];

const platform = $('Prepare TikTok Video Sync').first().json;
const periodStart = new Date(platform.period_start).getTime();
const periodEnd = new Date(platform.period_end).getTime();
const monitoredUsername = String(platform.tiktok_username || '').replace(/^@/, '').trim().toLowerCase();
const videos = platform.comment_target_videos ?? [];
const videoByUrl = new Map(videos.map(video => [String(video.video_url).split('?')[0], video]));
const output = [];
const rawItems = items.map(item => item.json);
const failures = rawItems.filter(item => item?.error || item?.errorCode || item?.errorDescription || item?.requestErrorMessages);
for (const comment of rawItems) {
  const commentId = comment.cid ?? comment.commentId ?? comment.id;
  const text = String(comment.text ?? '').trim();
  if (!commentId || !text) continue;
  const rawDate = comment.createTimeISO ?? comment.createTime;
  const commentDate = typeof rawDate === 'number' ? new Date(rawDate * 1000) : new Date(rawDate);
  const commentTime = commentDate.getTime();
  if (Number.isNaN(commentTime) || commentTime < periodStart || commentTime >= periodEnd) continue;
  const authorUsername = String(comment.uniqueId ?? comment.username ?? '').replace(/^@/, '').trim();
  if (monitoredUsername && authorUsername.toLowerCase() === monitoredUsername) continue;
  const videoUrl = String(comment.videoWebUrl ?? comment.videoUrl ?? '').trim();
  const video = videoByUrl.get(videoUrl.split('?')[0]);
  const urlVideoId = videoUrl.split('/video/')[1]?.split('?')[0]?.split('/')[0] ?? null;
  const replyToId = comment.repliesToId ?? comment.replyToCommentId ?? null;
  output.push({ json: {
    fetch_succeeded: true,
    has_comments: true,
    client_id: platform.client_id,
    branch_id: platform.branch_id ?? null,
    platform_id: platform.id,
    tiktok_comment_id: String(commentId),
    video_id: String(comment.aweme_id ?? comment.videoId ?? video?.video_id ?? urlVideoId ?? '') || null,
    comment_text: text,
    author_username: authorUsername || null,
    author_name: comment.nickname ?? null,
    author_avatar_url: comment.avatarThumbnail ?? null,
    video_url: videoUrl || video?.video_url || null,
    video_description: video?.description ?? null,
    posted_at: commentDate.toISOString(),
    public_metrics: {
      like_count: Number(comment.diggCount ?? comment.likes ?? 0) || 0,
      reply_count: Number(comment.replyCommentTotal ?? comment.replies ?? 0) || 0
    },
    is_reply: Boolean(replyToId),
    reply_to_comment_id: replyToId ? String(replyToId) : null,
    analysis_status: 'pending',
    raw_data: { comment, monitored_username: platform.tiktok_username || null, client_platform_id: platform.id }
  } });
}
if (output.length === 0) {
  return [{ json: {
    fetch_succeeded: failures.length === 0,
    has_comments: false,
    client_id: platform.client_id,
    branch_id: platform.branch_id ?? null,
    platform_id: platform.id,
    message: failures.length ? 'تعذر جلب تعليقات TikTok من Clockworks' : 'لا توجد تعليقات TikTok جديدة داخل الفترة المحددة'
  } }];
}
return output;
